/* =========================================================================
   worker-notificaciones — Cloudflare Worker (proyecto SEPARADO de la app)
   -------------------------------------------------------------------------
   "Mensajero" de recordatorios de Agenda: guarda en D1 cuándo hay que
   avisarle a cada suscripción push, y un Cron Trigger cada 1 minuto manda
   los que ya vencieron. Nunca accede a Google Drive ni ve datos académicos
   más allá del título/cuerpo cortos que la propia app decide mandarle (ver
   notificaciones-push.js en el cliente).

   Endpoints (todos bajo el dominio que Cloudflare asigna al Worker):
     POST   /programar        — upsert de un recordatorio por `id`.
     DELETE /programar/:id    — cancela (borra) un recordatorio pendiente.

   Handler programado (`scheduled`, cron cada 1 minuto — ver wrangler.toml):
     Manda los recordatorios vencidos y limpia suscripciones muertas.
   ========================================================================= */

import { enviarWebPush } from "./web-push.js";

// Dominio real de la app (GitHub Pages) — único origen que puede llamar a
// /programar; cualquier otro se rechaza antes de tocar D1. Un solo origen
// alcanza porque la app es una SPA de una sola página (no hay múltiples
// subdominios legítimos llamando a este Worker).
const ORIGEN_PERMITIDO = "https://waxyflounder971.github.io";

// Tope de envíos por corrida del cron: Cloudflare Workers en el plan
// gratuito permite hasta 50 subrequests por invocación: cada push implica
// 1 fetch al push service (Google/Mozilla/etc.) + alguna consulta a D1, así
// que 40 deja margen sin arriesgar el límite. Si algún minuto quedan más
// de 40 recordatorios vencidos, los que sobran simplemente se mandan en la
// corrida siguiente (1 minuto después) — no se pierden, solo se atrasan.
const TOPE_ENVIOS_POR_CORRIDA = 40;

function encabezadosCors(origen) {
  const permitido = origen === ORIGEN_PERMITIDO;
  return {
    "Access-Control-Allow-Origin": permitido ? origen : "null",
    "Access-Control-Allow-Methods": "POST, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
  };
}

function respuestaJson(cuerpo, status, origen) {
  return new Response(JSON.stringify(cuerpo), {
    status,
    headers: { "Content-Type": "application/json", ...encabezadosCors(origen) },
  });
}

/** POST /programar — valida el payload mínimo y hace upsert por `id`. */
async function manejarProgramar(request, env, origen) {
  let body;
  try {
    body = await request.json();
  } catch (e) {
    return respuestaJson({ error: "Body inválido (se esperaba JSON)." }, 400, origen);
  }

  const { id, suscripcion_push, fecha_hora_utc, titulo, cuerpo } = body || {};

  // Validación mínima: lo esencial para poder mandar el push más adelante.
  // No se valida la forma exacta de suscripcion_push acá (eso lo hace
  // fallar recién al intentar cifrar/enviar, en el cron) — alcanza con que
  // sea un objeto no vacío.
  if (
    !id || typeof id !== "string" ||
    !suscripcion_push || typeof suscripcion_push !== "object" || !suscripcion_push.endpoint ||
    !Number.isFinite(fecha_hora_utc) ||
    !titulo || typeof titulo !== "string"
  ) {
    return respuestaJson(
      { error: "Faltan campos requeridos: id, suscripcion_push (con endpoint), fecha_hora_utc, titulo." },
      400,
      origen
    );
  }

  await env.DB_NOTIFICACIONES.prepare(
    `INSERT INTO recordatorios (id, suscripcion_push, fecha_hora_utc, titulo, cuerpo, enviado)
     VALUES (?, ?, ?, ?, ?, 0)
     ON CONFLICT(id) DO UPDATE SET
       suscripcion_push = excluded.suscripcion_push,
       fecha_hora_utc = excluded.fecha_hora_utc,
       titulo = excluded.titulo,
       cuerpo = excluded.cuerpo,
       enviado = 0`
  )
    .bind(id, JSON.stringify(suscripcion_push), Math.floor(fecha_hora_utc), titulo, cuerpo || null)
    .run();

  return respuestaJson({ ok: true }, 200, origen);
}

/** DELETE /programar/:id — cancela un recordatorio pendiente (o ya enviado, da igual). */
async function manejarCancelar(id, env, origen) {
  if (!id) return respuestaJson({ error: "Falta el id en la URL." }, 400, origen);
  await env.DB_NOTIFICACIONES.prepare(`DELETE FROM recordatorios WHERE id = ?`).bind(id).run();
  return respuestaJson({ ok: true }, 200, origen);
}

/**
 * POST /prueba — notificación de bienvenida inmediata, apenas el usuario
 * activa el switch en Ajustes (ver activarNotificacionesPush en
 * notificaciones-push.js). A propósito NO toca D1: no es un recordatorio
 * programado, es solo una prueba end-to-end de "¿el pipeline completo
 * (claves VAPID + push service + tu Service Worker) funciona ahora
 * mismo?" — si esta notificación llega al dispositivo, ya está probado
 * todo sin tener que esperar al cron de 1 minuto ni crear un evento de
 * Agenda de prueba.
 */
async function manejarPrueba(request, env, origen) {
  let body;
  try {
    body = await request.json();
  } catch (e) {
    return respuestaJson({ error: "Body inválido (se esperaba JSON)." }, 400, origen);
  }

  const { suscripcion_push } = body || {};
  if (!suscripcion_push || typeof suscripcion_push !== "object" || !suscripcion_push.endpoint) {
    return respuestaJson({ error: "Falta suscripcion_push (con endpoint)." }, 400, origen);
  }

  try {
    const respuesta = await enviarWebPush({
      suscripcion: suscripcion_push,
      payloadObjeto: {
        titulo: "¡Notificaciones activadas! 🎉",
        cuerpo: "Todo quedó bien configurado — así se van a ver tus recordatorios reales de Agenda.",
      },
      vapidPublicKey: env.VAPID_CLAVE_PUBLICA,
      vapidPrivateKey: env.VAPID_CLAVE_PRIVADA,
      vapidSubject: env.VAPID_SUBJECT,
    });

    if (respuesta.ok) return respuestaJson({ ok: true }, 200, origen);

    // No se distingue 404/410 acá como en enviarRecordatorio: es una
    // suscripción recién creada hace segundos, no tendría sentido que ya
    // esté muerta — cualquier status de error se reporta tal cual para
    // que el cliente vea el motivo real en vez de un mensaje genérico.
    return respuestaJson({ ok: false, error: `El servicio de push devolvió status ${respuesta.status}.` }, 502, origen);
  } catch (e) {
    return respuestaJson({ ok: false, error: "No se pudo cifrar/enviar el push de prueba." }, 502, origen);
  }
}

/**
 * Manda un recordatorio ya vencido. Devuelve cómo terminó para que el
 * llamador decida qué hacer con la fila (marcar enviado, borrar, o dejarla
 * para reintentar en la próxima corrida).
 */
async function enviarRecordatorio(fila, env) {
  const suscripcion = JSON.parse(fila.suscripcion_push);
  try {
    const respuesta = await enviarWebPush({
      suscripcion,
      payloadObjeto: { titulo: fila.titulo, cuerpo: fila.cuerpo || "" },
      vapidPublicKey: env.VAPID_CLAVE_PUBLICA,
      vapidPrivateKey: env.VAPID_CLAVE_PRIVADA,
      vapidSubject: env.VAPID_SUBJECT,
    });

    if (respuesta.ok) return "enviado";

    // 404/410 = el navegador/usuario mató esta suscripción (desinstaló la
    // app, revocó el permiso, etc.) — el push service ya no la va a
    // aceptar nunca más, así que se borra la fila en vez de reintentar
    // indefinidamente contra un destino muerto.
    if (respuesta.status === 404 || respuesta.status === 410) return "suscripcion_muerta";

    // Cualquier otro status (429, 5xx del push service, etc.): error
    // transitorio — se deja la fila como está para que el cron de dentro
    // de 1 minuto la vuelva a intentar.
    console.warn(`Push de "${fila.id}" falló con status ${respuesta.status}, se reintenta en la próxima corrida.`);
    return "reintentar";
  } catch (e) {
    console.warn(`Push de "${fila.id}" falló (excepción), se reintenta en la próxima corrida:`, e);
    return "reintentar";
  }
}

/** Cron Trigger (cada 1 minuto, ver wrangler.toml): manda lo vencido. */
async function manejadorProgramado(env) {
  const ahora = Math.floor(Date.now() / 1000);

  const { results } = await env.DB_NOTIFICACIONES.prepare(
    `SELECT id, suscripcion_push, titulo, cuerpo FROM recordatorios
     WHERE enviado = 0 AND fecha_hora_utc <= ?
     ORDER BY fecha_hora_utc ASC
     LIMIT ?`
  )
    .bind(ahora, TOPE_ENVIOS_POR_CORRIDA)
    .all();

  if (!results || results.length === 0) return;

  for (const fila of results) {
    const resultado = await enviarRecordatorio(fila, env);
    if (resultado === "enviado" || resultado === "suscripcion_muerta") {
      // No hace falta conservar historial (ver spec A.3) — se borra en vez
      // de solo marcar enviado=1, así la tabla no crece sin límite.
      await env.DB_NOTIFICACIONES.prepare(`DELETE FROM recordatorios WHERE id = ?`).bind(fila.id).run();
    }
    // "reintentar": se deja la fila intacta a propósito.
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const origen = request.headers.get("Origin") || "";

    // Preflight CORS.
    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: encabezadosCors(origen) });
    }

    // El origen debe coincidir exacto con el dominio real de la app en
    // CUALQUIER endpoint — se corta acá antes de tocar D1 si no matchea.
    if (origen !== ORIGEN_PERMITIDO) {
      return respuestaJson({ error: "Origen no permitido." }, 403, origen);
    }

    if (request.method === "POST" && url.pathname === "/programar") {
      return manejarProgramar(request, env, origen);
    }

    if (request.method === "POST" && url.pathname === "/prueba") {
      return manejarPrueba(request, env, origen);
    }

    const matchCancelar = url.pathname.match(/^\/programar\/(.+)$/);
    if (request.method === "DELETE" && matchCancelar) {
      return manejarCancelar(decodeURIComponent(matchCancelar[1]), env, origen);
    }

    return respuestaJson({ error: "Not found." }, 404, origen);
  },

  async scheduled(event, env, ctx) {
    ctx.waitUntil(manejadorProgramado(env));
  },
};
